  Whatsapp_Message__c: {
    name: "Whatsapp_Message__c",
    label: "Whatsapp Message",
    description: "Contains details of the whatsapp message.",
    columns: [
      {"name": "Id", "type": "Id", "pk": true},
      {"name": "API_Error_Message__c", "label": "API Error Message", "type": "Long Text(32768)", "description": "Stores detailed information about any errors encountered during the API call to the WhatsApp messaging service."},
      {"name": "API_Request__c", "label": "API Request", "type": "Long Text(32768)", "description": "Stores the raw API request data sent to the WhatsApp messaging service for outbound communication with the customer."},
      {"name": "API_Response__c", "label": "API Response", "type": "Long Text(32768)", "description": "Stores the raw API response data received from the WhatsApp messaging service for both outbound and inbound communications."},
      {"name": "API_Status__c", "label": "API Status", "type": "Picklist", "description": "Indicates the outcome of the API call made to the WhatsApp messaging service for message delivery."},
      {"name": "Booking__c", "label": "Booking", "type": "Lookup", "fk": {"table": "Booking__c", "column": "Id"}},
      {"name": "Business_Phone_number__c", "label": "Business Phone number", "type": "Phone", "description": "Stores the business phone number used for sending or receiving WhatsApp messages to or from customers."},
      {"name": "Contains_File__c", "label": "Contains File", "type": "Checkbox", "description": "Indicates whether the WhatsApp message contains an attached file, such as an image, document, or video."},
      {"name": "Customer_phone__c", "label": "Customer phone", "type": "Phone", "description": "Stores the customer's phone number associated with the WhatsApp message for tracking communication with the specific customer."},
      {"name": "End_point__c", "label": "End point", "type": "Url", "description": "Stores the API endpoint URL used for sending or receiving WhatsApp messages through the messaging service."},
      {"name": "File_Name__c", "label": "File Name", "type": "Text(255)", "description": "File name of document file."},
      {"name": "Footer__c", "label": "Footer", "type": "Long Text(131072)", "description": "Stores any additional information or text that is added as a footer in the WhatsApp message."},
      {"name": "Interactive__c", "label": "Interactive", "type": "Checkbox", "description": "Indicates whether the WhatsApp message includes interactive elements such as buttons or quick replies"},
      {"name": "Is_audio__c", "label": "Is audio?", "type": "Checkbox", "description": "True if the message is a audio message."},
      {"name": "Is_video__c", "label": "Is video?", "type": "Checkbox", "description": "True if the message is a video message."},
      {"name": "Latitude__c", "label": "Latitude", "type": "Number", "description": "The latitude coordinate for the location associated with this WhatsApp message."},
      {"name": "Lead__c", "label": "Lead", "type": "Lookup", "fk": {"table": "Lead", "column": "Id"}, "description": "The Lead to whom the message belongs to."},
      {"name": "Location__c", "label": "Location", "type": "Location", "description": "Current location when the message was sent."},
      {"name": "Longitude__c", "label": "Longitude", "type": "Number", "description": "The longitude coordinate for the location associated with this WhatsApp message."},
      {"name": "Media_Id__c", "label": "Media Id", "type": "Text(255)", "description": "Stores the unique identifier for any media (such as images, videos, or documents) associated with the WhatsApp message."},
      {"name": "Media_Url__c", "label": "Media Url", "type": "Url", "description": "Stores the URL of the media file associated with the WhatsApp message."},
      {"name": "Message_Content__c", "label": "Message Content", "type": "Long Text(131072)", "description": "Stores the content of the WhatsApp message sent or received."},
      {"name": "Message_Id__c", "label": "Message Id", "type": "Text(200)", "description": "ID of the whatsapp message."},
      {"name": "Message_Type__c", "label": "Message Type", "type": "Picklist", "description": "Indicates the type of WhatsApp message being sent or received."},
      {"name": "Message_status__c", "label": "Message status", "type": "Picklist", "description": "whatsapp message status"},
      {"name": "Opportunity__c", "label": "Opportunity", "type": "Lookup", "fk": {"table": "Opportunity", "column": "Id"}},
      {"name": "Outbound__c", "label": "Outbound?", "type": "Checkbox", "description": "Checks whether the message is outbound or inbound."},
      {"name": "Parent_message_id__c", "label": "Parent Message Id", "type": "Text(255)", "description": "Stores the unique identifier of the parent message in a message thread or conversation."},
      {"name": "Public_Link__c", "label": "Public Link", "type": "Long Text(131072)", "description": "Contains public link generated from content distribution object of salesforce"},
      {"name": "Reaction__c", "label": "Reaction", "type": "Text(255)", "description": "Records the name of the emoji used in response to the WhatsApp message."},
      {"name": "Success__c", "label": "Success", "type": "Checkbox", "description": "Indicates whether the WhatsApp message was successfully processed."},
      {"name": "Template_Id__c", "label": "Template Id", "type": "Text(255)", "description": "Template Id generated by Meta of the WhatsApp template"},
      {"name": "Template_name__c", "label": "Template name", "type": "Text(255)", "description": "Name of the WhatsApp template"},
      {"name": "header__c", "label": "header", "type": "Long Text(131072)", "description": "Stores any additional information or text that is added as a header in the WhatsApp message."},
      {"name": "is_Document__c", "label": "is Document?", "type": "Checkbox", "description": "Indicates if the WhatsApp message contains document message."},
      {"name": "is_Location__c", "label": "is Location?", "type": "Checkbox", "description": "Indicates if the WhatsApp message contains location information."},
    ],
  },
